package com.gmail.manhle240406.project.adoption;
import android.content.*;import androidx.test.core.app.ActivityScenario;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import com.google.android.gms.tasks.Tasks;import com.google.firebase.auth.FirebaseAuth;import com.gmail.manhle240406.project.R;import org.junit.*;import org.junit.runner.RunWith;import java.util.*;import static org.junit.Assert.*;import static org.hamcrest.Matchers.*;import static androidx.test.espresso.Espresso.*;import static androidx.test.espresso.action.ViewActions.*;import static androidx.test.espresso.matcher.ViewMatchers.*;import static androidx.test.espresso.matcher.RootMatchers.isDialog;import static androidx.test.espresso.assertion.ViewAssertions.*;import static com.gmail.manhle240406.project.adoption.AdoptionFlowModel.*;

@RunWith(AndroidJUnit4.class) public class PermissionsUiTest {
 private final Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();private String uid;private final String id="30000000-0000-0000-0000-000000000001";private Map<String,Object> submitted,consent;private boolean held,restricted,ownerListing,rolloutEnabled=true;
 @Before public void setup(){uid=FirebaseAuth.getInstance().getUid();assertNotNull("Retain the user's existing signed-in account",uid);try(ActivityScenario<com.gmail.manhle240406.project.MainActivity> boot=ActivityScenario.launch(com.gmail.manhle240406.project.MainActivity.class)){assertTrue(UiDevice.getInstance(InstrumentationRegistry.getInstrumentation()).wait(Until.hasObject(By.res(c.getPackageName(),"nav_home")),30000));}AdoptionApi.testEnvelopeTransport=(op,input,accepted)->{
  if(op.equals("flowRead")){switch(String.valueOf(input.get("kind"))){case "listing":return Tasks.forResult(map("requirements",map("fields",map("description","Synthetic pet","temperament","Friendly","careRequirements","Daily care","adoptionRequirements","Safe home")),"isOwner",ownerListing,"canEdit",true));case "readiness":return Tasks.forResult(map("simplified",true,"enabled",rolloutEnabled,"email",true,"profile",true,"terms",false,"termsVersion",1L,"termsHash","exact-test-hash","termsText","Synthetic course terms"));case "request":return Tasks.forResult(map("request",map("requestId",id,"title","Synthetic request","hostUid","peer","adopterUid",uid,"status","SUBMITTED","version",1,"answers",map())));default:return Tasks.forResult(map("rows",Collections.emptyList()));}}
  if(op.equals("flow")){submitted=new HashMap<>(input);consent=accepted==null?null:new HashMap<>(accepted);return Tasks.forResult(map("requestId",id));}
  if(op.equals("pet"))return Tasks.forResult(map("pet",map("petId",id,"identityVersion",1L,"custodyVersion",0L),"claim",map("reviewState","self_declared_for_demo"),"care",map(),"revision",map(),"privateCare",null));
  if(op.equals("care")){submitted=new HashMap<>(input);return Tasks.forResult(map("careVersion",1L,"careDigest","synthetic-care-hash"));}
  if(op.equals("courseNotices"))return Tasks.forResult(map("rows",Arrays.asList(map("noticeId",id,"reason","Synthetic recipient explanation","state","active","version",1L,"appeal",null)),"next",null));
  if(op.equals("courseAccountRead"))return Tasks.forResult(map("account",map("uid","peer","alias","Synthetic account","directoryVersion",1L),"restrictionVersion",restricted?1L:0L,"decisions",restricted?Arrays.asList(map("decisionId",id,"scope","community_publication","reason","Synthetic restriction","version",1L)):Collections.emptyList()));
  if(op.equals("courseAccount")){submitted=new HashMap<>(input);restricted="precaution".equals(input.get("command"));return Tasks.forResult(map("version",1L));}
  if(op.equals("courseReport")){submitted=new HashMap<>(input);return Tasks.forResult(map("workId",id,"status","resolved_no_action"));}
  if(op.equals("courseReportRead"))return Tasks.forResult(map("report",map("reportId",id,"statement","Synthetic private report","targetKind","post","targetId",id,"parentId",null,"statusVersion",1L),"assignment",map("assignmentVersion",1L)));
  if(op.equals("courseAdminRead")){if("report".equals(input.get("kind")))return Tasks.forResult(map("rows",Arrays.asList(map("kind","report","targetId",id,"parentId",null,"title","Synthetic report category","state","received")),"next",null));if("target".equals(input.get("mode")))return Tasks.forResult(map("kind","post","targetId",id,"parentId",null,"sourceVersion",held?2L:1L,"ownerUid","peer","control",map("version",held?1L:0L,"state",held?"held":"clear","holdActionId",held?id:null)));return Tasks.forResult(map("rows",Arrays.asList(map("kind","post","targetId",id,"parentId",null,"title","Synthetic moderation content","state",held?"held":"clear")),"next",null));}
  if(op.equals("courseModerate")){submitted=new HashMap<>(input);held="hold".equals(input.get("command"));return Tasks.forResult(map("state",held?"held":"clear"));}return Tasks.forResult(map());};}
 @After public void end(){AdoptionApi.testEnvelopeTransport=null;AdoptionApi.testTransport=null;assertEquals(uid,FirebaseAuth.getInstance().getUid());}
 private void click(int label){onView(withText(label)).perform(scrollTo(),androidx.test.espresso.action.ViewActions.click());}
 @Test public void privateVerifiedMemberAppliesWithContextualAtomicConsentAndPreservedForm(){try(ActivityScenario<LifecycleActivity> s=ActivityScenario.launch(new Intent(c,LifecycleActivity.class).putExtra("listing",id))){click(R.string.lc_apply);onView(withText(R.string.lc_phone)).check(doesNotExist());for(String key:new String[]{"introduction","environment","care","experience"})onView(withTagValue(equalTo("lc_"+key))).perform(scrollTo(),replaceText("Synthetic answer "+key),androidx.test.espresso.action.ViewActions.closeSoftKeyboard());s.recreate();onView(withTagValue(equalTo("lc_introduction"))).check(matches(withText("Synthetic answer introduction")));click(R.string.lc_submit);onView(withText(android.R.string.cancel)).inRoot(isDialog()).perform(androidx.test.espresso.action.ViewActions.click());assertNull(submitted);click(R.string.lc_submit);onView(withText(R.string.permissions_agree_continue)).inRoot(isDialog()).perform(androidx.test.espresso.action.ViewActions.click());assertEquals("submit",submitted.get("command"));assertEquals("exact-test-hash",consent.get("termsHash"));assertEquals(1L,consent.get("termsVersion"));assertFalse(submitted.containsKey("participationConsent"));}}
 @Test public void closedRolloutExplainsAvailabilityAndDoesNotSubmit(){rolloutEnabled=false;try(ActivityScenario<LifecycleActivity> s=ActivityScenario.launch(new Intent(c,LifecycleActivity.class).putExtra("listing",id))){click(R.string.lc_apply);onView(withText(R.string.lc_disabled)).check(matches(isDisplayed()));onView(withText(R.string.lc_submit)).check(matches(not(isEnabled())));assertNull(submitted);}}
 @Test public void adminCanRestrictAndLiftAnExactAccountAction(){try(ActivityScenario<CourseAdminActivity> s=ActivityScenario.launch(CourseAdminActivity.class)){onView(withText(startsWith("Synthetic moderation content"))).perform(scrollTo(),androidx.test.espresso.action.ViewActions.click());click(R.string.permissions_manage_account);onView(isAssignableFrom(com.google.android.material.textfield.TextInputEditText.class)).perform(scrollTo(),replaceText("Synthetic account reason"),androidx.test.espresso.action.ViewActions.closeSoftKeyboard());click(R.string.permissions_restrict_posts);assertEquals("community_publication",submitted.get("scope"));assertEquals("precaution",submitted.get("command"));onView(isAssignableFrom(com.google.android.material.textfield.TextInputEditText.class)).perform(scrollTo(),replaceText("Restriction lifted after review"),androidx.test.espresso.action.ViewActions.closeSoftKeyboard());click(R.string.permissions_lift_restriction);assertEquals("lift",submitted.get("command"));assertFalse(restricted);}}
 @Test public void adminClaimsAndRespondsToAssignedReport(){try(ActivityScenario<CourseAdminActivity> s=ActivityScenario.launch(CourseAdminActivity.class)){onView(isAssignableFrom(android.widget.Spinner.class)).perform(androidx.test.espresso.action.ViewActions.click());onData(equalTo(c.getResources().getStringArray(R.array.permissions_content_types)[5])).perform(androidx.test.espresso.action.ViewActions.click());onView(withText(startsWith("Synthetic report category"))).perform(scrollTo(),androidx.test.espresso.action.ViewActions.click());assertEquals("claim",submitted.get("command"));onView(withText("Synthetic private report")).check(matches(isDisplayed()));onView(isAssignableFrom(com.google.android.material.textfield.TextInputEditText.class)).perform(scrollTo(),replaceText("Reviewed with explanation"),androidx.test.espresso.action.ViewActions.closeSoftKeyboard());click(R.string.permissions_report_no_action);assertEquals("resolved_no_action",submitted.get("outcome"));assertEquals("Reviewed with explanation",submitted.get("response"));}}
 @Test public void publishedOwnerListingShowsDetailsWithoutAnotherPreparationStep(){ownerListing=true;try(ActivityScenario<LifecycleActivity> s=ActivityScenario.launch(new Intent(c,LifecycleActivity.class).putExtra("listing",id))){onView(withText(R.string.permissions_listing_details)).check(matches(isDisplayed()));onView(withText(R.string.lc_save)).check(doesNotExist());onView(withText(R.string.lc_phone)).check(doesNotExist());onView(withText(R.string.permissions_update_offer)).perform(scrollTo()).check(matches(isDisplayed()));assertNull(submitted);}}
 @Test public void currentCaregiverEditsCareWithoutApprovalOrPhoneChecklist(){try(ActivityScenario<AdoptionFlowActivity> s=ActivityScenario.launch(new Intent(c,AdoptionFlowActivity.class).putExtra("mode","care").putExtra("petId",id))){onView(withText(R.string.ad_submit_claim)).check(doesNotExist());onView(withText(R.string.lc_phone)).check(doesNotExist());onView(withTagValue(equalTo("ad_medication"))).perform(scrollTo(),replaceText("Synthetic private care note"),androidx.test.espresso.action.ViewActions.closeSoftKeyboard());onView(withTagValue(equalTo("adoption_save_care"))).perform(androidx.test.espresso.action.ViewActions.click());assertEquals("Synthetic private care note",submitted.get("medicationNotes"));assertEquals(1L,submitted.get("expectedIdentityVersion"));long deadline=android.os.SystemClock.uptimeMillis()+10000;while(s.getState()!=androidx.lifecycle.Lifecycle.State.DESTROYED&&android.os.SystemClock.uptimeMillis()<deadline){InstrumentationRegistry.getInstrumentation().waitForIdleSync();android.os.SystemClock.sleep(25);}assertEquals("Care screen exits after the committed save",androidx.lifecycle.Lifecycle.State.DESTROYED,s.getState());}}
 @Test public void adminCanHoldAndRestoreThroughManagedTaskWithoutRawWrites(){try(ActivityScenario<CourseAdminActivity> s=ActivityScenario.launch(CourseAdminActivity.class)){onView(withText(startsWith("Synthetic moderation content"))).perform(scrollTo(),androidx.test.espresso.action.ViewActions.click());onView(isAssignableFrom(com.google.android.material.textfield.TextInputEditText.class)).perform(scrollTo(),replaceText("Synthetic policy reason"),androidx.test.espresso.action.ViewActions.closeSoftKeyboard());click(R.string.permissions_hold);assertEquals("hold",submitted.get("command"));assertTrue(held);onView(withText(startsWith("Synthetic moderation content"))).perform(scrollTo(),androidx.test.espresso.action.ViewActions.click());onView(isAssignableFrom(com.google.android.material.textfield.TextInputEditText.class)).perform(scrollTo(),replaceText("Corrected content"),androidx.test.espresso.action.ViewActions.closeSoftKeyboard());click(R.string.permissions_restore);assertEquals(id,submitted.get("holdActionId"));assertFalse(held);}}
 @Test public void recipientReadsOwnReasonAndFilesOwnAppealWithoutAdminChecklist(){try(ActivityScenario<CourseNoticesActivity> s=ActivityScenario.launch(CourseNoticesActivity.class)){onView(withText("Synthetic recipient explanation")).check(matches(isDisplayed()));onView(isAssignableFrom(android.widget.Spinner.class)).perform(androidx.test.espresso.action.ViewActions.click());onData(equalTo(c.getResources().getStringArray(R.array.permissions_notice_types)[1])).perform(androidx.test.espresso.action.ViewActions.click());click(R.string.permissions_appeal);onView(isAssignableFrom(com.google.android.material.textfield.TextInputEditText.class)).inRoot(isDialog()).perform(replaceText("Please reconsider this synthetic restriction"),androidx.test.espresso.action.ViewActions.closeSoftKeyboard());onView(withText(R.string.lc_submit)).inRoot(isDialog()).perform(androidx.test.espresso.action.ViewActions.click());assertEquals("appeal",submitted.get("command"));assertEquals(id,submitted.get("decisionId"));assertEquals(1L,submitted.get("expectedVersion"));onView(withText(R.string.permissions_appeal_recorded)).check(matches(isDisplayed()));}}

}
